<script setup lang="ts">
import { computed, ref } from 'vue'
import EmpirePage from '../components/EmpirePage.vue'
import StudioIcon from '../components/StudioIcon.vue'
import { RANKS, rankByKey, type EmpireState, type Officer, type OfficialRole } from '../core/empire'
const props = defineProps<{ state: EmpireState }>()
const emit = defineEmits<{ notice: [string]; edict: [Officer] }>()
const view = ref<'ranks' | 'roster'>('ranks'), roleFilter = ref('all'), rankFilter = ref('all'), query = ref('')
const editor = ref<HTMLDialogElement | null>(null), titleEditor = ref<HTMLDialogElement | null>(null)
const editingId = ref<string | null>(null), editingRank = ref('1-zheng')
const form = ref({ name: '', role: 'civil' as OfficialRole, rank: '9-zheng', duty: '' })
const titleForm = ref({ civil: '', military: '' }), error = ref(''), titleError = ref('')
const removed = ref<{ officer: Officer; index: number } | null>(null)
const roleLabel = (role: OfficialRole) => role === 'civil' ? '文官' : '武官'
const title = (o: Pick<Officer, 'rank' | 'role'>) => props.state.rankTitles[o.rank][o.role]
const civilCount = computed(() => props.state.officers.filter(o => o.role === 'civil').length)
const militaryCount = computed(() => props.state.officers.filter(o => o.role === 'military').length)
const filtered = computed(() => props.state.officers.filter(o => (roleFilter.value === 'all' || o.role === roleFilter.value) && (rankFilter.value === 'all' || o.rank === rankFilter.value) && `${o.name} ${o.duty} ${title(o)} ${rankByKey(o.rank).label}`.includes(query.value.trim())).sort((a,b) => rankByKey(a.rank).order - rankByKey(b.rank).order || a.role.localeCompare(b.role) || a.name.localeCompare(b.name, 'zh-CN')))
const rankCount = (key: string, role: OfficialRole) => props.state.officers.filter(o => o.rank === key && o.role === role).length
function edit(officer?: Officer) { editingId.value = officer?.id ?? null; form.value = { name: officer?.name ?? '', role: officer?.role ?? 'civil', rank: officer?.rank ?? '9-zheng', duty: officer?.duty ?? '' }; error.value = ''; editor.value?.showModal() }
function submit() {
  const data = { ...form.value, name: form.value.name.trim(), duty: form.value.duty.trim() }
  if (!data.name || Array.from(data.name).length > 12 || Array.from(data.duty).length > 160 || !RANKS.some(r => r.key === data.rank) || !['civil','military'].includes(data.role)) { error.value = '请填写姓名，并选择文武类别和品级。'; return }
  const existing = props.state.officers.find(o => o.id === editingId.value)
  if (editingId.value && !existing) { error.value = '这位官员已移出官册。'; return }
  if (existing) Object.assign(existing, data)
  else { if (props.state.officers.length >= 200) { error.value = '官册最多收录 200 人。'; return }; props.state.officers.push({ id: crypto.randomUUID(), ...data }) }
  editor.value?.close(); emit('notice', '官册已更新')
}
function remove() { const index = props.state.officers.findIndex(o => o.id === editingId.value); if (index < 0) return; removed.value = { officer: { ...props.state.officers[index] }, index }; props.state.officers.splice(index, 1); editor.value?.close() }
function restore() { if (!removed.value || props.state.officers.length >= 200) return; props.state.officers.splice(removed.value.index, 0, removed.value.officer); removed.value = null }
function editTitles(key: string) { if (key === 'unranked') return; editingRank.value = key; titleForm.value = { ...props.state.rankTitles[key] }; titleError.value = ''; titleEditor.value?.showModal() }
function submitTitles() {
  const civil = titleForm.value.civil.trim(), military = titleForm.value.military.trim()
  if (!civil || !military || Array.from(civil).length > 24 || Array.from(military).length > 24) { titleError.value = '文官和武官职名均须填写，最多 24 字。'; return }
  if (civil === military) { titleError.value = '文官与武官请设置不同的职名。'; return }
  props.state.rankTitles[editingRank.value] = { civil, military }; titleEditor.value?.close(); emit('notice', '文武职名已更新')
}
function showRank(key: string, role: OfficialRole) { rankFilter.value = key; roleFilter.value = role; query.value = ''; view.value = 'roster' }
</script>
<template>
  <EmpirePage title="文武百官" eyebrow="THE IMPERIAL COURT" description="文以治国，武以安邦。共用十九档品级，各有文武职名。">
    <template #actions><span class="court-count">文官 {{ civilCount }} · 武官 {{ militaryCount }}</span><button class="button management-primary" :disabled="state.officers.length >= 200" @click="edit()">＋ 录入官员</button></template>
    <div class="court-view management-tabs"><button :aria-pressed="view === 'ranks'" @click="view = 'ranks'">品级官制</button><button :aria-pressed="view === 'roster'" @click="view = 'roster'">文武官册</button></div>
    <section v-if="view === 'ranks'" class="management-card rank-register" aria-label="十九品级官制"><div class="rank-intro"><h2>九品十八阶，另设不入流</h2><p>正一品最高；同一品内，正品高于从品。文官与武官品级相同，职名分别设置。</p></div><div class="management-table-wrap"><table class="management-table rank-table"><thead><tr><th>品级</th><th>文官职名</th><th>武官职名</th><th>职名设置</th></tr></thead><tbody><tr v-for="rank in RANKS" :key="rank.key"><td><span class="rank-order">{{ String(rank.order + 1).padStart(2, '0') }}</span>{{ rank.label }}</td><td><span>{{ state.rankTitles[rank.key].civil }}</span><button v-if="rankCount(rank.key, 'civil')" class="rank-count" :aria-label="`查看${rank.label}文官`" @click="showRank(rank.key, 'civil')">{{ rankCount(rank.key, 'civil') }} 人 ↗</button></td><td><span>{{ state.rankTitles[rank.key].military }}</span><button v-if="rankCount(rank.key, 'military')" class="rank-count" :aria-label="`查看${rank.label}武官`" @click="showRank(rank.key, 'military')">{{ rankCount(rank.key, 'military') }} 人 ↗</button></td><td><button v-if="rank.key !== 'unranked'" class="text-button" :aria-label="`设置${rank.label}职名`" @click="editTitles(rank.key)">设置职名</button><span v-else class="field-note">不入流小官</span></td></tr></tbody></table></div></section>
    <section v-else aria-label="文武官册"><div class="management-toolbar"><div class="management-tabs"><button :aria-pressed="roleFilter === 'all'" @click="roleFilter = 'all'">文武总览</button><button :aria-pressed="roleFilter === 'civil'" @click="roleFilter = 'civil'">文官</button><button :aria-pressed="roleFilter === 'military'" @click="roleFilter = 'military'">武官</button></div><select v-model="rankFilter" class="management-select" aria-label="筛选官员品级"><option value="all">所有品级</option><option v-for="rank in RANKS" :key="rank.key" :value="rank.key">{{ rank.label }}</option></select><input v-model="query" class="text-input" aria-label="搜索官员" placeholder="搜索姓名、职名、职掌…" /><span class="management-summary">{{ filtered.length }} 人</span></div><div v-if="removed" class="management-restore" role="status">已移出 {{ removed.officer.name }}<button class="text-button" :disabled="state.officers.length >= 200" @click="restore">恢复入册</button></div><p v-if="!filtered.length" class="management-card management-empty">{{ state.officers.length ? '当前筛选没有匹配的官员。' : '朝堂待贤，录入第一位官员。' }}</p><div v-else class="officer-grid"><article v-for="officer in filtered" :key="officer.id" class="management-card officer-card"><div class="officer-top"><span class="management-badge">{{ roleLabel(officer.role) }} · {{ rankByKey(officer.rank).label }}</span><button class="text-button" :aria-label="`编辑官员${officer.name}`" @click="edit(officer)">编辑</button></div><span class="officer-office">{{ title(officer) }}</span><h2>{{ officer.name }}</h2><p>{{ officer.duty || '职掌待定' }}</p><button class="text-button" :aria-label="`为${officer.name}拟任命旨`" @click="emit('edict', officer)"><StudioIcon name="stamp" :size="14" />拟任命旨 ↗</button></article></div></section>
  </EmpirePage>
  <dialog ref="editor" class="help-dialog management-dialog" aria-labelledby="officer-title" @click="$event.target === editor && editor?.close()"><button class="icon-button dialog-close" aria-label="关闭官员编辑" @click="editor?.close()"><StudioIcon name="close" /></button><span class="eyebrow">COURT REGISTER</span><h2 id="officer-title">{{ editingId ? '编辑官员' : '录入官员' }}</h2><form class="management-form" @submit.prevent="submit"><label>官员姓名<input v-model="form.name" class="text-input" maxlength="12" required /></label><div class="management-form-row"><label>文武类别<select v-model="form.role" class="management-select"><option value="civil">文官</option><option value="military">武官</option></select></label><label>官员品级<select v-model="form.rank" class="management-select"><option v-for="rank in RANKS" :key="rank.key" :value="rank.key">{{ rank.label }}</option></select></label></div><p class="field-note">职名：{{ title(form) }} · {{ rankByKey(form.rank).label }}</p><label>职掌<textarea v-model="form.duty" class="text-input" maxlength="160" placeholder="写下职责与任职说明…" /></label><p v-if="error" class="overflow-warning" role="alert">{{ error }}</p><div class="management-form-actions"><button v-if="editingId" class="text-button" type="button" @click="remove">移出官册</button><button class="button management-primary" type="submit">保存官员</button></div></form></dialog>
  <dialog ref="titleEditor" class="help-dialog management-dialog" aria-labelledby="rank-title" @click="$event.target === titleEditor && titleEditor?.close()"><button class="icon-button dialog-close" aria-label="关闭职名设置" @click="titleEditor?.close()"><StudioIcon name="close" /></button><span class="eyebrow">RANK TITLES</span><h2 id="rank-title">{{ rankByKey(editingRank).label }} · 文武职名</h2><form class="management-form" @submit.prevent="submitTitles"><label>文官职名<input v-model="titleForm.civil" class="text-input" maxlength="24" required /></label><label>武官职名<input v-model="titleForm.military" class="text-input" maxlength="24" required /></label><p class="field-note">职名修改会同步至该品级官员，品级顺序固定。</p><p v-if="titleError" class="overflow-warning" role="alert">{{ titleError }}</p><div class="management-form-actions"><button class="button management-primary" type="submit">保存职名</button></div></form></dialog>
</template>
<style scoped>
.court-count { color: var(--muted); font-size: 12px; white-space: nowrap; }.court-view { margin-bottom: 24px; }.rank-intro { display: flex; gap: 20px; flex-wrap: wrap; align-items: baseline; margin-bottom: 14px; }.rank-intro h2 { font: 18px var(--font-serif); margin: 0; letter-spacing: 2px; }.rank-intro p { font-size: 11px; color: var(--muted); line-height: 1.9; margin: 0; }.rank-table { min-width: 560px; }.rank-table td { padding-top: 14px; padding-bottom: 14px; }.rank-order { font: 9px var(--font-sans); color: var(--muted); margin-right: 16px; }.rank-count { background: none; border: 0; color: var(--accent); margin-left: 18px; padding: 0; font-size: 10px; }.officer-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; }.officer-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; }.officer-office { display: block; color: var(--accent); font: 13px var(--font-serif); letter-spacing: 2px; margin-top: 24px; overflow-wrap: anywhere; }.officer-card h2 { font: 25px var(--font-serif); letter-spacing: 4px; margin: 12px 0; overflow-wrap: anywhere; }.officer-card p { font-size: 11px; color: var(--muted); line-height: 1.9; min-height: 42px; overflow-wrap: anywhere; }.officer-card > .text-button { margin-top: 15px; }
@media (max-width: 1100px) { .officer-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@media (max-width: 850px) { .officer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 480px) { .officer-grid { grid-template-columns: 1fr; } }
</style>
